"use server";

import { db } from "@/lib/db";
import { rateLimit } from "@/lib/security";
import { leadSchema } from "@/lib/validators";
import { after } from "next/server";
import { sendLeadAlert } from "@/lib/email";

export type LeadState = { ok?: boolean; error?: string; fieldErrors?: Record<string, string[] | undefined> } | undefined;

const DETAIL_FIELDS = ["requirement", "quantity", "timeline", "budget", "product", "text", "material", "occasion", "gst"] as const;

export async function submitLead(_: LeadState, formData: FormData): Promise<LeadState> {
  if (!(await rateLimit("lead", 6, 60 * 60))) return { error: "Too many submissions. Please call or WhatsApp us instead." };
  const raw = Object.fromEntries(formData);
  const details: Record<string, string> = {};
  for (const f of DETAIL_FIELDS) {
    const all = formData.getAll(f).map(String).filter(Boolean);
    if (all.length) details[f] = all.join(", ").slice(0, 500);
  }
  const parsed = leadSchema.safeParse({ ...raw, details });
  if (!parsed.success) return { fieldErrors: parsed.error.flatten().fieldErrors };
  if (parsed.data.website) return { ok: true }; // honeypot hit: pretend success

  const { website: _hp, email, ...data } = parsed.data;
  void _hp;
  await db.lead.create({ data: { ...data, email: email || null } });
  after(() => sendLeadAlert({ ...data, email }));
  return { ok: true };
}
